objectCard.openedEventHandler:
      
        if(data.requisites.find(re => re.name == "CanSign").value === false || 
           data.requisites.find(re => re.name == "CanSign").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Sign"), 1);
        }
        if(data.requisites.find(re => re.name == "CanApprove").value === false || 
           data.requisites.find(re => re.name == "CanApprove").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Approve"), 1);
        }
        if(data.requisites.find(re => re.name == "CanAcquainted").value === false || 
           data.requisites.find(re => re.name == "CanAcquainted").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Acquainted"), 1);
        }
        if(data.requisites.find(re => re.name == "CanForReapproving").value === false || 
           data.requisites.find(re => re.name == "CanForReapproving").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Reapproving"), 1);
        }
        if(data.requisites.find(re => re.name == "CanReject").value === false || 
           data.requisites.find(re => re.name == "CanReject").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Reject"), 1);
        }
        if(data.requisites.find(re => re.name == "CanForRevision").value === false || 
           data.requisites.find(re => re.name == "CanForRevision").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Revision"), 1);
        }

        resolve({configuration: configuration, data: data});
